when.set-body:
@{
                    var src = context.Response.Body.As<JObject>();
                    var result = new JArray();
                    var rows = src["value"] as JArray;
                    if (rows != null) {
                        foreach (var row in rows) {
                            var o = new JObject();
                            o["id"] = row["RowKey"];
                            o["name"] = row["name"];
                            o["email"] = row["email"];
                            if (row["city"] != null) { o["city"] = row["city"]; }
                            result.Add(o);
                        }
                    }
                    return result.ToString();
                }
